def minimalBases(classes):
    try:
        if not isinstance(classes, list):
            raise TypeError("Input must be a list of base classes.")
        if not classes:
            return []

        # Filter out non-class types
        filtered_classes = [cls for cls in classes if isinstance(cls, type)]
        if not filtered_classes:
            return []

        # Remove duplicates while preserving order
        seen = set()
        unique_classes = []
        for cls in filtered_classes:
            if cls not in seen:
                seen.add(cls)
                unique_classes.append(cls)

        # Remove subclasses: if a class is a subclass of another class in the list, remove it
        minimal = []
        for cls in unique_classes:
            is_subclass_of_another = False
            for other in unique_classes:
                if cls != other and issubclass(cls, other):
                    is_subclass_of_another = True
                    break
            if not is_subclass_of_another:
                minimal.append(cls)

        return minimal
    except Exception:
        return []

