def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if not hasattr(self, 'data') or not hasattr(self, 'edges'):
            raise AttributeError("Histogram not properly initialized.")

        if not isinstance(coord, (tuple, list)):
            coord = (coord,)

        if len(coord) != len(self.edges):
            raise ValueError(f"Coordinate length {len(coord)} does not match number of dimensions {len(self.edges)}")

        # Build a list of indices for each dimension
        indices = []
        for i, (c, edges) in enumerate(zip(coord, self.edges)):
            if edges is None:
                raise ValueError(f"Edges for dimension {i} are not set.")
            if not isinstance(edges, (list, tuple)) or len(edges) < 2:
                raise ValueError(f"Edges for dimension {i} must have at least two values.")

            # Ensure edges are sorted
            if edges[0] >= edges[-1]:
                raise ValueError(f"Edges for dimension {i} are not in increasing order.")

            # Check if coordinate is within the range
            if c < edges[0] or c > edges[-1]:
                return  # Ignore points outside the histogram

            # Determine bin index
            # Find the rightmost edge that is <= coord
            # Linear search for simplicity
            for j in range(1, len(edges)):
                if edges[j] > c:
                    indices.append(j - 1)
                    break
            else:
                # c == edges[-1], so last bin
                indices.append(len(edges) - 2)

        # Convert indices to a tuple key for the data dict
        key = tuple(indices)

        if not hasattr(self, 'data'):
            self.data = {}

        self.data[key] = self.data.get(key, 0) + weight

