    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    import krake.common
    from krake.commons import fun
    from krake.data.config import ObserverSchema

    try:
        # Get the manifest of the app
        manifest = fun.getattr(app.spec, 'manifest', None)
        if not manifest:
            return app

        # If no observer schemas specified, generate default ones
        observer_schemas = fun.getattr(app.spec, 'observer', None)
        if not observer_schemas:
