        for resource_type, resources in manifest.items():
            if not resources:
                continue

            for resource_name in resources.keys():
                # Check if observer schema for this resource is already specified
                existing_schema = None
                if observer_schemas.resources:
                    existing_schema = observer_schemas.resources.get(resource_type, {}).get(resource_name, None)

                if existing_schema is None:
                    # Generate a default observer schema
                    default_schema = ObserverSchema.ResourceSchema(
                        enabled=True
                    )

                    if not observer_schemas.resources:
                        observer_schemas.resources = {}
                    if resource_type not in observer_schemas.resources:
                        observer_schemas.resources[resource_type] = {}
                    observer_schemas.resources[resource_type][resource_name] = default_schema

        return app

    except Exception as e:
