        # Check for the version directory
        version_dir = self.fs.joinpath(path, '1')
        if not self.fs.isdir(version_dir):
            return False

        # Check for content directory
        content_dir = self.fs.joinpath(path, 'content')
        if not self.fs.isdir(content_dir):
            return False

        # Check for inventory.json in the version directory
        inventory_path = self.fs.joinpath(version_dir, 'inventory.json')
        if not self.fs.exists(inventory_path):
            return False

        # Optionally validate the inventory JSON structure
        try:
