def _explore_zipfile(zip_path):
        file_groups = {}
        if not zip_path or not isinstance(zip_path, str):
            raise ValueError("Invalid zip_path. It must be a non-empty string.")

        if not os.path.exists(zip_path):
            raise FileNotFoundError(f"Zip file not found: {zip_path}")

        if not zipfile.is_zipfile(zip_path):
            raise ValueError(f"Provided path is not a valid zip file: {zip_path}")

        with zipfile.ZipFile(zip_path, "r") as zip_file:
            for file_info in zip_file.infolist():
                file_name = file_info.filename
                if file_info.is_dir():
                    continue

                # Split the path into directory and basename
                dirname, basename = os.path.split(file_name)

                # Check if the basename ends with .xml
                if not basename.lower().endswith(".xml"):
                    continue

                # Get the XML basename (without the extension)
                xml_basename = os.path.splitext(basename)[0]

                # Group the file path under its XML basename
                if xml_basename not in file_groups:
                    file_groups[xml_basename] = []

                file_groups[xml_basename].append(file_name)

        return file_groups

