    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from sympy.core.sympify import sympify
    from sympy.logic.boolalg import (
        And, Or, Not, ArgumentIndexError, BooleanFunction, True_, False_
    )

    # Handle edge cases
    if not args:
        return list(args)

    # Convert all args to sympy expressions
    args = [sympify(arg) for arg in args]

    changed = True
    while changed:
        changed = False
        new_args = []
        for a in args:
