    required_keys = {
        'branch': '',
        'distance': None,
        'dirty': False,
        'error': None,
        'full': '',
        'date': None
    }
    required_keys.update(pieces)

    if style == "pep440":
        # Simplified PEP 440 logic
        if required_keys.get("error"):
