def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("Version must be a string")

    # Split the version into parts by dots
    parts = version.split(".")

    # Check if all parts are valid integers (allowing for leading zeros)
    for part in parts:
        if part == "":
            raise ValueError("Empty version part detected")
        try:
            int(part)
        except ValueError:
            raise ValueError(f"Invalid version part: {part}")

    # If the version has no digits, return "1"
    if not parts:
        return "1"

    # Find the rightmost part to increment
    # We'll increment the last part first
    last_index = len(parts) - 1
    parts[last_index] = str(int(parts[last_index]) + 1)

    # Remove leading zeros from all parts (standard versioning doesn't use leading zeros
    # except for "0" itself)
    cleaned_parts = []
    for part in parts:
        # Convert to int to remove leading zeros, then back to string
        # Special case: if it's "0", keep it as "0"
        if part == "0":
            cleaned_parts.append("0")
        else:
            cleaned_parts.append(str(int(part)))

    return ".".join(cleaned_parts)

