def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        return

    for version_dir in version_dirs:
        inventory_path = os.path.join(self.versions_path, version_dir, self.INVENTORY_FILENAME)
        if not os.path.isfile(inventory_path):
            self.log.warning(f"Missing inventory for version {version_dir}")
            continue

        try:
            with open(inventory_path, 'r') as f:
                inventory = self._load_inventory(f)
        except Exception as e:
            self.log.error(f"Failed to load inventory for version {version_dir}: {e}")
            continue

        for oid, entry in inventory.items():
            digest = entry.get(self.DIGEST_KEY)
            if digest and digest not in self.root_inventory.get(oid, {}).get(self.DIGEST_KEY, [None]):
                if oid not in self.digest_differences:
                    self.digest_differences[oid] = set()
                self.digest_differences[oid].add(digest)

