def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f"Error: path does not exist: {path}"

        if os.path.isdir(path):
            # Check for OCFL Storage Root or Object using Namaste files "0=*"
            name = os.path.basename(path)
            # If the path name starts with digits followed by "=", e.g., "0=xxx"
            if name.startswith("0="):
                # Looks like an OCFL Object or Storage Root. Let's see if it looks like an Object.
                # An object typically has a directory with the same Namaste name? 
                # Actually, in OCFL, the Object is identified by its directory name ending in "0=xxx".
                # So for a path like /storage/root/0=abc, the basename is "0=abc" which is an Object.
                # For a path like /storage/root, it's a Root if it contains objects.
                pass

            # Let's check the basename
            # If the directory name is like "0=...", it's an object
            if name.startswith("0="):
                # Could also be a root if it contains "0=" directories, but
                # in this simple implementation, let's check the contents
                try:
                    if os.path.isdir(path):
                        entries = os.listdir(path)
                        # Check if it has any "0=" entries (objects)
                        object_entries = [e for e in entries if e.startswith("0=")]
                        if object_entries:
                            return 'root'
                        else:
                            # If it's named 0=... but no objects, could still be object (maybe in mock/setup phase)
                            # We checked basename, so let's be more robust
                            return 'object'
                    else:
                        return 'object'
                except OSError:
                    return f"Error: cannot access directory: {path}"
            else:
                # If the directory does not start with "0=", check if it looks like a root
                try:
                    if os.path.isdir(path):
                        entries = os.listdir(path)
                        # Check if it has any "0=" entries (objects)
                        object_entries = [e for e in entries if e.startswith("0=")]
                        if object_entries:
                            return 'root'
                        else:
                            return f"Error: path is directory but not an OCFL root or object: {path}"
                    else:
                        return f"Error: expected directory, got: {path}"
                except OSError:
                    return f"Error: cannot access directory: {path}"

        elif os.path.isfile(path):
            return 'file'

        else:
            return f"Error: path is neither file nor directory: {path}"

    except Exception as e:
        return f"Error: unexpected exception: {e}"

