    flags = []
    for action in parser._actions:
        if action.help == SUPPRESS or action.dest == SUPPRESS:
            continue
        # For positional arguments, get the flag from the option string or from the dest
        if action.option_strings:
            flags.extend(action.option_strings)
        else:
            # For positional arguments, use the dest
            flags.append(action.dest)
    # Remove duplicates while preserving order
