def size_to_bytes(size: str) -> int:
    import re

    # Define size units and their corresponding bytes
    units = {
        'B': 1,
        'K': 1000,
        'M': 1000 ** 2,
        'G': 1000 ** 3,
        'T': 1000 ** 4,
        'P': 1000 ** 5,
        'E': 1000 ** 6,
    }

    # Strip whitespace
    size = size.strip()

    # Check if the input is valid
    if not size:
        return 0

    # Match the pattern: optional number, optional decimal, optional unit
    match = re.match(r'^([0-9]*\.?[0-9]+)\s*([BKGTP]?)(...)?$', size, re.IGNORECASE)
    if not match:
        # Also allow suffixes without 'B'
        match = re.match(r'^([0-9]*\.?[0-9]+)\s*([KMGTP]?)(...)?$', size, re.IGNORECASE)

    # More flexible pattern
    match = re.match(r'^([0-9]*\.?[0-9]+)\s*([BKMGTPE]?)(...)?$', size, re.IGNORECASE)
    if not match:
        # Allow standalone numbers
        if size.replace('.', '', 1).isdigit():
            return int(float(size)) if '.' in size else int(size)
        return 0

    number_str = match.group(1)
    unit = (match.group(2) or 'B').upper()

    if unit not in units:
        return 0

    try:
        value = float(number_str)
    except ValueError:
        return 0

    bytes_value = value * units[unit]

    # Return integer representation
    return int(round(bytes_value))

