def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        roots.add(o)

    for s, p, o in graph.triples((None, prop, None)):
        if s not in roots:
            continue
        if o in roots:
            roots.discard(o)

    return roots

