    # Fallback: try to iterate
    try:
        it = iter(seq)
        first = next(it)
        # Since we consumed the first element, we need to reconstruct the sequence
        # if it was an iterator. We'll assume it's a generator-like object.
        # To be safe, we put the first element back by constructing a new sequence.
        rest = list(it)
        seq = (first,) + tuple(rest)
        return seq, type(first)
    except (StopIteration, TypeError, AttributeError):
        # We could not extract a first element; default to the original seq and object type
        return seq, type(seq)

