def determine_metaclass(bases, explicit_mc=None):
    """
    Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: tuple of base classes
    :param explicit_mc: optional explicit metaclass
    :return: the most derived metaclass
    """
    if not bases:
        raise TypeError("There must be at least one base class")

    # Start with the explicit metaclass if provided, otherwise type
    if explicit_mc is not None:
        metaclass = explicit_mc
    else:
        metaclass = type(bases[0])
        # Get metaclasses from all bases
        for base in bases[1:]:
            base_mc = type(base)
            # Choose the most derived metaclass
            if issubclass(base_mc, metaclass):
                metaclass = base_mc
            elif issubclass(metaclass, base_mc):
                continue
            else:
                raise TypeError(
                    "metaclass conflict: "
                    "the metaclass must be a "
                    "non-transparent subclass of the "
                    "metaclasses of all the bases"
                )

    return metaclass

