def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    if not settings_dirs:
        return []
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple")
    file_names = []
    for settings_dir in settings_dirs:
        if settings_dir:
            file_names.extend([str(file) for file in os.listdir(settings_dir) if os.path.isfile(os.path.join(settings_dir, file)) and file.endswith(spec_option)])
    return file_names

