    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    try:
        # Prepare extra-vars for Ansible CLI
        extra_vars = []
        for key, value in vars_dict.items():
            # Convert to string in JSON format for complex values
            if isinstance(value, (dict, list)):
                import json
                extra_vars.append(f"@{key}={json.dumps(value)}")
            else:
                extra_vars.append(f"@{key}={json.dumps(value)}")

        # Build the Ansible CLI command
        command = ['ansible-playbook']

        # Add extra vars
        if extra_vars:
            command.extend(['--extra-vars', ' '.join(extra_vars)])

        # Add all other CLI arguments
        command.extend(cli_args)

