                'stdout': process.stdout.decode(),
                'stderr': process.stderr.decode()
            }
        else:
            return {
                'status': 'failure',
                'stdout': process.stdout.decode(),
                'stderr': process.stderr.decode()
            }
    except Exception as e:
        return {
            'status': 'error',
